import {art, photo, image, esc} from './ui.js';
import {searchFields} from './search-fields.js';
import {compactPropertyCard} from './refresh-cards.js';
import {catalogData} from '../catalog-page/data.js';
import {articles} from './data.js';

export const featuredProperties = catalogData.properties.slice(0, 4);
export const catalogCategories = ['Квартиры', 'Новостройки', 'Дома', 'Коммерческая', 'Участки'];
export const icon = (name, className='') => {
  const paths = {
    arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
    diagonal:'<path d="M6 18 18 6M6 6h12v12"/>',
    back:'<path d="M19 12H5m6-6-6 6 6 6"/>',
    search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
    phone:'<path d="m8 3 3 5-3 3a15 15 0 0 0 5 5l3-3 5 3c0 3-2 5-5 5C9 21 3 15 3 8c0-3 2-5 5-5Z"/>',
    message:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2V11.5a9.5 9.5 0 0 1 19 0Z"/><path d="M7 10h9M7 14h6"/>',
    check:'<path d="m5 12 4 4L19 6"/>',
    menu:'<path d="M4 8h16M4 16h16"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',
  };
  return `<svg class="ui-icon ${className}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.arrow}</svg>`;
};
export const cta = (label, topic=label, secondary=false) => `<button class="r-button ${secondary?'r-button-secondary':''}" data-consult="${esc(topic)}"><span>${esc(label)}</span><span class="button-icon">${icon('diagonal')}</span></button>`;
export const sectionHead = (number, title, description='') => `<div class="r-section-head"><div><p class="r-kicker"><span>${number}</span> Квадрат · недвижимость</p><h2>${title}</h2></div>${description?`<p class="r-section-description">${description}</p>`:''}</div>`;
export const contactGroup = () => `<div class="contact-group" role="group" aria-label="Связаться с агентством"><button data-consult="Написать агенту" aria-label="Написать агенту">${icon('message')}</button><button data-consult="Заказать звонок" aria-label="Заказать звонок">${icon('phone')}</button></div>`;

export function refreshHeader(){return `<header class="r-header r-container"><a class="r-brand" href="homepage.html" aria-label="Квадрат — главная">${image(art('logo.svg'),'Квадрат — агентство недвижимости','', 'width="190" height="99"')}</a><nav class="r-navigation" id="primary-navigation" aria-label="Основная навигация"><a href="property-catalog.html">Недвижимость</a><a href="#services">Услуги</a><a href="#about">О Квадрате</a><a href="#blog">Журнал</a><a href="#contacts">Контакты</a></nav><div class="header-actions"><button class="header-contact" data-consult="Обсудим вашу задачу">Обсудим задачу ${icon('diagonal')}</button><button class="menu-toggle" aria-expanded="false" aria-controls="primary-navigation" aria-label="Открыть меню">${icon('menu')}</button></div></header>`;}
export function refreshHero(){return `<div class="r-intro ruled-dark">${image(photo('0f3b9ff0a9e2ef25.jpg'),'','hero-architecture','fetchpriority="high" width="2000" height="1125"')}${refreshHeader()}<section class="r-hero r-container" aria-labelledby="hero-title"><div class="r-hero-copy"><p class="r-kicker"><span class="location-dot"></span> Агентство недвижимости · Оренбург</p><h1 id="hero-title">Новый адрес.<br><span>Ваша история.</span></h1><p class="r-hero-description">Недвижимость для жизни и ваших планов.<br> С личным агентом, который на вашей стороне.</p><div class="r-hero-actions"><a class="r-button" href="#search"><span>Найти своё место</span><span class="button-icon">${icon('diagonal')}</span></a><a class="hero-about-link" href="#about">Познакомиться с Квадратом ${icon('arrow')}</a></div></div><div class="hero-side-note"><span class="tiny-cross" aria-hidden="true">+</span><p>Важен не только адрес.<br>Важно, как вы себя<br>здесь чувствуете.</p><span class="hero-note-line"></span><small>Квадрат. На вашей стороне.</small></div><div class="hero-bottom"><span>Покупка · Продажа · Аренда</span><a href="#search">Начните с поиска ${icon('arrow')}</a></div></section>${refreshSearch()}</div>`;}
export function refreshSearch(){return `<section class="r-search r-container" id="search" aria-labelledby="search-title"><div class="search-heading"><h2 id="search-title">Место для ваших планов</h2><span>Выберите главное. Остальное найдём вместе.</span></div><form action="property-catalog.html" method="get" class="property-search" aria-label="Подбор недвижимости">${searchFields()}<button class="r-button search-button" type="submit">${icon('search')}<span>Найти объекты</span></button></form><div class="search-suggestions"><span>Можно начать с этого</span><a href="property-catalog.html?deal=buy&amp;type=flat&amp;market=secondary&amp;rooms=1">Первая квартира ${icon('diagonal')}</a><a href="property-catalog.html?deal=buy&amp;type=flat&amp;market=secondary&amp;rooms=3">Больше места для семьи ${icon('diagonal')}</a><button data-consult="Помогите выбрать недвижимость">Помогите определиться ${icon('diagonal')}</button></div></section>`;}
export function refreshCatalog(){return `<section class="r-catalog r-section r-container" id="catalog">${sectionHead('01','У каждого дома —<br>своя история. Найдите вашу.','От первого собственного жилья<br> до пространства для большой семьи.')}<div class="catalog-toolbar"><div class="catalog-tabs" role="tablist" aria-label="Тип недвижимости">${catalogCategories.map((label,i)=>`<button role="tab" id="category-${i}" aria-controls="property-list" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-category="${i}">${label}</button>`).join('')}</div><a class="r-text-link" href="property-catalog.html">Весь каталог ${icon('diagonal')}</a></div><div id="property-list" role="tabpanel" aria-labelledby="category-0" tabindex="0"><div class="property-grid">${featuredProperties.map(compactPropertyCard).join('')}</div><p class="catalog-message" role="status" hidden></p></div><div class="catalog-bottom"><p>Объекты и цены из исходного макета</p><div class="carousel-controls"><span class="carousel-position" aria-live="polite">01 / 04</span><div class="carousel-arrows" role="group" aria-label="Карточки недвижимости"><button data-carousel="catalog" data-step="-1" aria-label="Предыдущая карточка">${icon('back')}</button><button data-carousel="catalog" data-step="1" aria-label="Следующая карточка">${icon('arrow')}</button></div></div></div><aside class="personal-selection" id="consultation"><div class="selection-mark" aria-hidden="true">${image(art('home.svg'))}</div><div><h3>Ваш вариант ещё впереди.</h3><p>Расскажите, что ищете. Подберём недвижимость под вашу жизнь.</p></div><div class="selection-actions">${cta('Подобрать с агентом')}${contactGroup()}</div></aside></section>`;}
const services = [
 ['Купить','Найдём пространство для жизни','Отберём варианты, организуем просмотры и поможем пройти весь путь до ключей.','Покупка недвижимости'],
 ['Продать','Поможем двигаться дальше','Определим цену, подготовим объект к продаже и найдём подходящего покупателя.','Продажа недвижимости'],
 ['Снять или сдать','Соединим ваши интересы','Поможем найти жильё или арендатора и договориться о понятных условиях.','Аренда недвижимости'],
];
export function refreshServices(){return `<section class="r-services ruled-dark" id="services"><div class="r-container r-section">${sectionHead('02','Большие перемены.<br>Спокойные решения.','Один личный агент и команда специалистов.<br> Рядом на каждом этапе сделки.')}<div class="r-services-grid">${services.map(([title,subtitle,description,topic],i)=>`<article class="r-service"><span class="service-index">0${i+1}</span><h3>${title}</h3><p class="service-subtitle">${subtitle}</p><p>${description}</p><button class="r-service-link" data-consult="${topic}"><span>Обсудить задачу</span>${icon('diagonal')}</button></article>`).join('')}</div><div class="service-extras"><p>Детали тоже берём на себя</p><div class="service-extra-group"><button data-consult="Оценка недвижимости">Оценка недвижимости ${icon('plus')}</button><button data-consult="Юридическое сопровождение">Юридическое сопровождение ${icon('plus')}</button><button data-consult="Покупка от застройщика">Покупка от застройщика ${icon('plus')}</button></div></div></div></section>`;}
export function refreshMortgage(){return `<section class="r-mortgage r-container r-section" id="mortgage"><div class="mortgage-copy"><p class="r-kicker"><span>03</span> Финансовая сторона</p><h2>Сначала — ясность.<br>Потом — ключи.</h2><p>Поможем разобраться в ипотечных программах, сопоставить условия и спланировать комфортный платёж.</p><ul class="mortgage-benefits"><li>${icon('check')} Подбор программы под вашу ситуацию</li><li>${icon('check')} Помощь с документами и заявкой</li><li>${icon('check')} Сопровождение до сделки</li></ul>${cta('Поговорить об ипотеке')}</div><div class="mortgage-preview"><div class="mortgage-preview-top"><span>ВАШ БУДУЩИЙ ДОМ</span>${icon('diagonal')}</div><h3>Всё начинается<br>с понятного плана.</h3><div class="plan-drawing">${image(art('search_plan.png'),'Планировка квартиры','', 'loading="lazy"')}</div><button class="mortgage-calc-link" data-calculator><span>${icon('plus')} Рассчитать платёж</span>${icon('arrow')}</button><p>Предварительный расчёт под ваши параметры</p></div></section>`;}
export function refreshAbout(){return `<section class="r-about r-container" id="about"><div class="about-visual">${image(photo('5205626077cfec78.jpg'),'Жилой квартал','about-city','loading="lazy"')}<span class="about-image-caption">Город знакомый. Возможности новые.</span><div class="about-image-brand">${image(art('logo.svg'),'Квадрат','', 'loading="lazy"')}</div></div><div class="about-content"><p class="r-kicker"><span>04</span> Люди, которым доверяют</p><h2>На вашей стороне.<br>От знакомства<br>до новоселья.</h2><p>За каждой сделкой — чья-то новая глава. Поэтому мы начинаем с разговора: о том, что для вас важно, как вы живёте и что хотите изменить.</p><p>Ваш агент остаётся рядом: помогает сравнить варианты, задаёт нужные вопросы и объясняет каждый следующий шаг.</p><div class="agent-signature"><div class="agent-avatar">${image(photo('880316dc7fbbcd57.png'),'Гульмира Суеналимова','', 'loading="lazy"')}</div><div><b>Гульмира Суеналимова</b><span>Директор агентства «Квадрат»</span></div><button data-consult="Познакомиться с командой" aria-label="Познакомиться с командой">${icon('diagonal')}</button></div></div></section>`;}
export function refreshJournal(){return `<section class="r-journal r-container r-section" id="blog"><span id="news"></span>${sectionHead('05','Хорошие решения<br>начинаются с понимания.','Спокойно разбираемся в недвижимости.<br> Без сложных слов и лишней спешки.')}<div class="journal-grid">${articles.filter(a=>['walls','documents','new-home'].includes(a.id)).map((a,i)=>`<article class="journal-card ${i===0?'journal-feature':''}">${i===0?`<div class="journal-image">${image(photo('41cd0a0530a4be35.jpg'),'Архитектура жилого дома','', 'loading="lazy"')}</div>`:''}<div class="journal-card-body"><p class="r-kicker">${esc(a.category)} <span>0${i+1}</span></p><h3><button data-article="${a.id}">${esc(a.title).replace(' - ',' — ')}</button></h3><div class="journal-meta"><span>Советы Квадрата</span><button data-article="${a.id}" aria-label="Читать: ${esc(a.title)}">${icon('diagonal')}</button></div></div></article>`).join('')}</div></section>`;}
export function refreshClosing(){return `<section class="r-closing ruled-dark" id="offers"><div class="r-container"><div class="closing-top"><p class="r-kicker">Следующая глава — ваша</p><span class="closing-mark" aria-hidden="true">↗</span></div><h2>Давайте найдём<br><span>ваш Квадрат.</span></h2><div class="closing-bottom"><p>Можно начать с вопроса.<br>Мы внимательно выслушаем и предложим следующий шаг.</p><div class="selection-actions">${cta('Начать разговор')}${contactGroup()}</div></div></div></section>`;}
export function refreshFooter(){return `<footer class="r-footer" id="contacts"><div class="r-container"><div class="footer-top"><a class="r-brand" href="homepage.html">${image(art('logo-dark.svg'),'Квадрат — агентство недвижимости','', 'width="190" height="99" loading="lazy"')}</a><p>Недвижимость для жизни.<br>Люди на вашей стороне.</p><button class="footer-contact" data-consult="Связаться с агентством">Связаться с нами ${icon('diagonal')}</button></div><div class="footer-nav"><nav aria-label="Недвижимость"><h3>Найти своё</h3><a href="property-catalog.html">Квартиры</a><a href="property-catalog.html?market=new">Новостройки</a><a href="property-catalog.html?type=house">Дома</a></nav><nav aria-label="Услуги агентства"><h3>Решить задачу</h3><a href="#services">Покупка и продажа</a><a href="#mortgage">Ипотека</a><button data-consult="Юридическое сопровождение">Сопровождение сделки</button></nav><nav aria-label="Об агентстве"><h3>Квадрат</h3><a href="#about">О нас</a><a href="#blog">Журнал</a><button data-consult="Познакомиться с командой">Знакомство с командой</button></nav><div class="footer-note"><p>Оренбург</p><span>Начнём с ваших планов.<br>Обсудим детали лично.</span>${contactGroup()}</div></div><div class="footer-bottom"><p>© Квадрат, 2026</p><span>Концепция главной · данные демонстрационные</span><a href="index.html#pages">Все макеты ${icon('diagonal')}</a></div></div></footer>`;}
export function renderRefresh(){return `${refreshHero()}<div class="r-content">${refreshCatalog()}${refreshServices()}${refreshMortgage()}${refreshAbout()}${refreshJournal()}</div>${refreshClosing()}${refreshFooter()}`;}
